$repo = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$sourceCommit = (git -C $repo rev-parse "$SourceCommit^{commit}").Trim()
if ($LASTEXITCODE -ne 0 -or [string]::IsNullOrWhiteSpace($sourceCommit)) {
    throw 'Stage 6 source commit is unavailable'
}
$sourceTree = (git -C $repo rev-parse "$sourceCommit^{tree}").Trim()
$currentTree = (git -C $repo write-tree).Trim()
if ($LASTEXITCODE -ne 0 -or $currentTree -ne $sourceTree) {
    throw 'Stage 6 source commit does not match the indexed build tree'
}
$output = Join-Path $repo 'build/stage6-release'
if (Test-Path -LiteralPath $output) { Remove-Item -LiteralPath $output -Recurse -Force }
$artifacts = Join-Path $output 'artifacts'
